import {trialState,channelFlow,CHANNEL_LINKS,rotateChannel,stepWardens,resetTrial,WARDEN_WALLS,WARDEN_GOALS} from './court-trials.js?v=0.90.52';
import {PALADIN_HONOURS} from './paladin-honours.js?v=0.90.52';
export function handleCourtTrial(id,a){const {state,openModal,$,document,rewardTransaction,buildMarkers,toast}=a;
 const commit=fn=>{let changed=false;const saved=rewardTransaction(()=>changed=fn());if(saved&&changed)buildMarkers();return saved&&changed;};
 const common='<p class="court-trial-note">No timer. Each move is saved. You can leave and return, or reset this trial.</p>';
 const channels=()=>{const t=trialState(state).channels,f=channelFlow(t.turns);openModal('The Shared Spring · Huonquet’s trial',`<p>Huonquet’s Mark of Honour protected Water Abyssals. Olivynx sheltered the living groves. Turn the nine stone channels to water <b>all three habitats</b> without spilling into the nesting ground.</p><p>The spring enters at the <b>middle left</b>. All three outlets are on the <b>right</b>. Water passes only between touching, open channel ends. Press a tile to turn it clockwise; its root-linked partner turns anticlockwise. The small numbers show which stones are linked.</p><div class="court-water-layout"><span>Spring →</span><div class="court-channel-board" aria-label="Nine rotating stone water channels">${f.masks.map((m,i)=>`<button data-court-channel="${i}" class="court-channel ${f.wet.includes(i)?'wet':''}" aria-label="Channel row ${Math.floor(i/3)+1} column ${i%3+1}, open ${['north','east','south','west'].filter((_,n)=>m&(1<<n)).join(', ')}" ${t.solved?'disabled':''}>${[1,2,4,8].map((bit,d)=>m&bit?`<i class="arm arm-${d}"></i>`:'').join('')}<i class="channel-centre"></i><small>${i+1} ↔ ${CHANNEL_LINKS[i]+1}</small></button>`).join('')}</div><div class="court-habitats">${['Pool','Grove','Reeds'].map((v,i)=>`<span class="${f.outlets[i]?'watered':''}">${f.outlets[i]?'●':'○'} ${v}</span>`).join('')}</div></div><p role="status">${t.solved?'<b>Mark restored. The river feeds every habitat; the first roots loosen.</b>':`Habitats fed: ${f.outlets.filter(Boolean).length}/3 · Spills: ${f.leaks} · Turns: ${t.moves}`}</p>${common}${t.solved?'':'<button id="court-trial-reset">Reset these channels</button>'}<details><summary>Read the keeper’s relief</summary><p>“The spring bends around the western root. The lowest bough carries water to the middle nest. Leave no open mouth drinking into bare earth.” The relief shows Water and Grass Abyssals sharing the same river, beneath Karolion’s tempered crown.</p></details>`);for(const e of document.querySelectorAll('[data-court-channel]'))e.onclick=()=>{if(commit(()=>rotateChannel(state,Number(e.dataset.courtChannel)))){channels();if(trialState(state).channels.solved)toast('The Shared Spring restored.');}};$('#court-trial-reset')?.addEventListener('click',()=>{if(commit(()=>resetTrial(state,'channels')))channels();});};
 const wardens=()=>{const t=trialState(state).wardens,p=t.positions;openModal('The Banked Ember · The Thawing Shield',`<p>Fieraguar kept Fire in check; Ogyon guarded Ice without letting winter swallow the river. Guide <b>Fire</b> and <b>Ice</b> to their matching sanctuaries.</p><p>Fire moves with your command. Ice moves in the <b>opposite direction</b>. A wall or edge holds that guardian still while the other can move. They cannot occupy the same square. Use the four command buttons below.</p><div class="court-warden-board" aria-label="Five by five linked guardian trial">${Array.from({length:25},(_,i)=>{const x=i%5,y=Math.floor(i/5),wall=WARDEN_WALLS.some(a=>a[0]===x&&a[1]===y),fire=p[0]===x&&p[1]===y,ice=p[2]===x&&p[3]===y,fg=WARDEN_GOALS[0]===x&&WARDEN_GOALS[1]===y,ig=WARDEN_GOALS[2]===x&&WARDEN_GOALS[3]===y;return `<div class="warden-cell ${wall?'root-wall':''} ${fg?'fire-goal':''} ${ig?'ice-goal':''}" aria-label="Row ${y+1} column ${x+1}: ${wall?'roots':fire?'Fire guardian':ice?'Ice guardian':fg?'Fire sanctuary':ig?'Ice sanctuary':'empty'}">${wall?'Roots':fire?'<img src="assets/419.webp" alt="Fieraguar"><b>FIRE</b>':ice?'<img src="assets/416.webp" alt="Ogyon"><b>ICE</b>':fg?'Fire':ig?'Ice':''}</div>`;}).join('')}</div><div class="court-warden-controls">${['up','left','down','right'].map(d=>`<button data-court-warden="${d}" ${t.solved?'disabled':''}>${{up:'↑ North',left:'← West',down:'↓ South',right:'East →'}[d]}</button>`).join('')}</div><p role="status">${t.solved?'<b>Both guardians keep their bounds. The second roots loosen.</b>':'Moves: '+t.moves+' · Both guardians must stand on their own sanctuary together.'}</p>${common}${t.solved?'':'<button id="court-trial-reset">Reset the guardians</button>'}<details><summary>Read the keeper’s relief</summary><p>“A steward must sometimes hold their ground so another can reach safety. Neither the ember nor the frost may take the other’s refuge.” The lower carving is worn away. The roots themselves remain in place.</p></details>`);for(const e of document.querySelectorAll('[data-court-warden]'))e.onclick=()=>{if(commit(()=>stepWardens(state,e.dataset.courtWarden))){wardens();if(trialState(state).wardens.solved)toast('The elemental wardens are in balance.');}else toast('The roots hold both guardians, or their paths would collide.');};$('#court-trial-reset')?.addEventListener('click',()=>{if(commit(()=>resetTrial(state,'wardens')))wardens();});};
 if(id==='court-root-channels'){if(!state.paladinCourt?.accepted){toast('Speak to Agnes at the Forgotten Turn first.');return true;}channels();return true;}
 if(id==='court-twin-wardens'){if(!state.paladinCourt?.accepted){toast('Speak to Agnes at the Forgotten Turn first.');return true;}wardens();return true;}
 if(id==='court-honours'){const honours=()=>{const q=state.paladinCourt;openModal('The Thirteen Marks of Honour',`${q?.sequence?.length&&!q.puzzle?`<p><b>Your submitted Marks:</b> ${q.sequence.map(k=>({'crown':'Tempered Crown','ember':'Banked Ember','night':'Unbarred Night','bough':'Living Bough','spring':'Shared Spring','thaw':'Thawing Shield'}[k]||k)).join(' → ')}</p><button id="court-oath-reset">Lift the submitted Marks · restart this oath</button>`:''}<p>Karolion’s court was a fellowship of stewards. Each Mark recognised service to Abyssals of one type and restraint of that element. No Mark granted ownership of its creatures. The ruined trials test those duties.</p>${PALADIN_HONOURS.map(h=>`<article class="court-honour"><h3>${h.name} · ${h.type}</h3><b>${h.mark}</b><p>${h.duty}</p></article>`).join('')}`);$('#court-oath-reset')?.addEventListener('click',()=>{if(commit(()=>{if(!state.paladinCourt?.sequence?.length||state.paladinCourt.puzzle)return false;state.paladinCourt.sequence=[];return true;}))honours();});};honours();return true;}return false;
}
